  pt:[['我离不开{x}。','Wǒ lí bu kāi {x}.','Я не могу без {x}.','tech'],['{x}让生活更方便。','{x} ràng shēnghuó gèng fāngbiàn.','{x} делает жизнь удобнее.','tech',3]],
